import{_ as t,o,c as s,a3 as a}from"./chunks/framework.BTQ4eCVb.js";const h=JSON.parse('{"title":"Reseller Payouts — Developer Guide","description":"","frontmatter":{"head":[["meta",{"property":"og:title","content":"Reseller Payouts — Developer Guide | EloSync Docs"}],["meta",{"property":"og:description","content":"Official documentation for the EloSync SaaS Platform."}],["meta",{"property":"og:url","content":"https://docs.elosync.com/developer-guide/reseller-payouts"}],["meta",{"property":"og:image","content":"https://docs.elosync.com/og-image.svg"}],["meta",{"name":"twitter:card","content":"summary_large_image"}],["meta",{"name":"twitter:title","content":"Reseller Payouts — Developer Guide | EloSync Docs"}],["meta",{"name":"twitter:description","content":"Official documentation for the EloSync SaaS Platform."}],["meta",{"name":"twitter:image","content":"https://docs.elosync.com/og-image.svg"}],["link",{"rel":"canonical","href":"https://docs.elosync.com/developer-guide/reseller-payouts"}]]},"headers":[],"relativePath":"developer-guide/reseller-payouts.md","filePath":"developer-guide/reseller-payouts.md","lastUpdated":1788507692000}'),r={name:"developer-guide/reseller-payouts.md"};function d(i,e,l,n,c,p){return o(),s("div",null,[...e[0]||(e[0]=[a(`<h1 id="reseller-payouts-—-developer-guide" tabindex="-1">Reseller Payouts — Developer Guide <a class="header-anchor" href="#reseller-payouts-—-developer-guide" aria-label="Permalink to &quot;Reseller Payouts — Developer Guide&quot;">​</a></h1><p>Phase 1 Sales companion. Slug <code>reseller-payouts</code>, middleware <code>module:reseller-payouts</code>, permissions <code>reseller-payouts.*</code>. Hard catalog dependency on <strong>Resellers</strong>. Partner directory: <a href="/developer-guide/resellers">Resellers</a>.</p><h2 id="backend-layout" tabindex="-1">Backend layout <a class="header-anchor" href="#backend-layout" aria-label="Permalink to &quot;Backend layout&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Piece</th><th>Path</th></tr></thead><tbody><tr><td>Model</td><td><code>app/Models/ResellerCommissionEntry.php</code></td></tr><tr><td>Enums</td><td><code>ResellerCommissionPartyEnum</code> (<code>reseller</code> | <code>owner</code>), <code>ResellerCommissionStatusEnum</code> (<code>accrued</code> | <code>approved</code> | <code>paid</code> | <code>void</code>)</td></tr><tr><td>Service</td><td><code>app/Services/Tenant/ResellerCommissionService.php</code></td></tr><tr><td>Controller</td><td><code>app/Http/Controllers/Tenant/Api/V1/ResellerCommissionEntryController.php</code></td></tr><tr><td>Resources</td><td><code>app/Http/Resources/Tenant/Api/V1/Reseller/*CommissionEntry*</code></td></tr><tr><td>Policy</td><td><code>app/Policies/ResellerCommissionEntryPolicy.php</code></td></tr><tr><td>Accrue listener</td><td><code>app/Listeners/AccrueResellerCommission.php</code> ← <code>CustomerInvoiceBecamePaid</code></td></tr><tr><td>Void listener</td><td><code>app/Listeners/VoidResellerCommission.php</code> ← <code>CustomerInvoiceLeftPaid</code></td></tr><tr><td>Transition helper</td><td><code>app/Support/Billing/CustomerInvoicePaidTransitions.php</code></td></tr><tr><td>Tests</td><td><code>tests/Feature/Tenant/Reseller/ResellerCommissionTest.php</code></td></tr></tbody></table><p>Registered in <code>AppServiceProvider</code> (<code>Event::listen</code> for both Paid enter/leave events).</p><h2 id="accrual-rules" tabindex="-1">Accrual rules <a class="header-anchor" href="#accrual-rules" aria-label="Permalink to &quot;Accrual rules&quot;">​</a></h2><p><code>ResellerCommissionService::accrueForPaidInvoice</code>:</p><ol><li>Skip if <code>invoice.reseller_id</code> is null</li><li>Skip if tenant lacks <code>reseller-payouts</code> entitlement</li><li>Skip if reseller row missing</li><li>Compute cuts from <strong>current</strong> reseller rates and invoice <code>total</code>:</li></ol><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>resellerCut = round(total * (commission_rate / 100), 2)</span></span>
<span class="line"><span>ownerCut    = round((total - resellerCut) * (owner_commission_rate / 100), 2)</span></span></code></pre></div><ol start="5"><li><code>ensurePartyEntry</code> on <code>(customer_invoice_id, party)</code> — creates accrued rows, or <strong>revives</strong> void rows with refreshed amounts/rates (clears approve/pay/void metadata). Existing non-void rows are left unchanged (idempotent).</li><li>Initial status <code>accrued</code>; currency from invoice (default <code>USD</code>)</li></ol><p><strong>Fully Paid only</strong> — listeners fire when status transitions <strong>into</strong> <code>CustomerInvoiceStatusEnum::Paid</code> (not Partial). Leaving Paid runs <code>voidForInvoice</code>, which bulk-voids <strong>every</strong> non-void row for that invoice (including <code>paid</code>). Re-paying the invoice revives those void rows. The manual <code>void()</code> API still rejects entries already in <code>paid</code>.</p><h2 id="workflow-guards" tabindex="-1">Workflow guards <a class="header-anchor" href="#workflow-guards" aria-label="Permalink to &quot;Workflow guards&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Method</th><th>Rule</th></tr></thead><tbody><tr><td><code>approve</code></td><td>status must be <code>accrued</code></td></tr><tr><td><code>pay</code></td><td>status must be <code>approved</code></td></tr><tr><td><code>void</code></td><td>not already <code>void</code>; cannot void <code>paid</code></td></tr></tbody></table><h2 id="assignee-visibility-scoping" tabindex="-1">Assignee / visibility scoping <a class="header-anchor" href="#assignee-visibility-scoping" aria-label="Permalink to &quot;Assignee / visibility scoping&quot;">​</a></h2><p>List/stats/view (policy + query): without <code>resellers.assign</code> and not superadmin → <code>party_user_id = actor</code> <strong>or</strong> reseller’s <code>user_id = actor</code>. Approve/pay/void are permission-only (not scoped to assignee).</p><h2 id="permissions" tabindex="-1">Permissions <a class="header-anchor" href="#permissions" aria-label="Permalink to &quot;Permissions&quot;">​</a></h2><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>reseller-payouts.view | approve | pay | void</span></span></code></pre></div><p>Default map: admin (all four); manager (view + approve); staff/reseller (view).</p><h2 id="api-tenant" tabindex="-1">API (tenant) <a class="header-anchor" href="#api-tenant" aria-label="Permalink to &quot;API (tenant)&quot;">​</a></h2><p>Base: <code>/api/tenant/v1</code> — <a href="/api/tenant-v1-reseller-payouts">tenant-v1-reseller-payouts.md</a>.</p><table tabindex="0"><thead><tr><th>Method</th><th>Path</th><th>Permission</th></tr></thead><tbody><tr><td>GET</td><td><code>/reseller-commission-entries</code></td><td>view</td></tr><tr><td>GET</td><td><code>/reseller-commission-entries/stats</code></td><td>view</td></tr><tr><td>GET</td><td><code>/reseller-commission-entries/{id}</code></td><td>view</td></tr><tr><td>POST</td><td><code>/reseller-commission-entries/{id}/approve</code></td><td>approve</td></tr><tr><td>POST</td><td><code>/reseller-commission-entries/{id}/pay</code></td><td>pay</td></tr><tr><td>POST</td><td><code>/reseller-commission-entries/{id}/void</code></td><td>void</td></tr></tbody></table><h2 id="frontend" tabindex="-1">Frontend <a class="header-anchor" href="#frontend" aria-label="Permalink to &quot;Frontend&quot;">​</a></h2><p>Phase 1 is backend API. SPA should follow the Leads/Vendors list + action pattern under Sales when shipped (<code>module: &#39;reseller-payouts&#39;</code>, <code>permission: reseller-payouts.view</code>).</p><h2 id="tests" tabindex="-1">Tests <a class="header-anchor" href="#tests" aria-label="Permalink to &quot;Tests&quot;">​</a></h2><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">php</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> artisan</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> test</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --compact</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> tests/Feature/Tenant/Reseller/ResellerCommissionTest.php</span></span></code></pre></div><h2 id="logging" tabindex="-1">Logging <a class="header-anchor" href="#logging" aria-label="Permalink to &quot;Logging&quot;">​</a></h2><p>Spatie <code>LogsActivity</code> on <code>ResellerCommissionEntry</code> (log name <code>reseller_commission_entries</code>).</p><h2 id="deferred" tabindex="-1">Deferred <a class="header-anchor" href="#deferred" aria-label="Permalink to &quot;Deferred&quot;">​</a></h2><ul><li>Cross-workspace identity for parties</li><li>Gateway disbursement / Connect payouts</li><li>Accrual on Partial status</li><li>Rate change recalculation after accrue</li></ul>`,29)])])}const m=t(r,[["render",d]]);export{h as __pageData,m as default};
